// lib/pdf-fonts.ts - V3.0a
// Polices embarquees pour jsPDF (rendu PDF identique au dashboard Next.js).
//
// Hanken Grotesk : 5 poids (400, 500, 600, 700, 800)
// Spline Sans Mono : 3 poids (400, 500, 600)
//
// Source : @fontsource (subset Latin, normal) - Google Fonts officiel
//          converti woff2 -> TTF via fonttools, puis encode en base64.
// Format : raw base64 (SANS prefixe data:font/truetype;base64,) - requis par jsPDF.addFileToVFS().
//
// Taille totale ~250 Ko (8 fichiers TTF latin subset, ~30 Ko + ~25 Ko chacun).
// Embarques dans le bundle pour que les PDF generes cote serveur (route API)
// ou cote client (telechargement direct) aient strictement le meme rendu.
//
// V3.0a : les polices sont ENREGISTREES dans le document jsPDF mais ne sont
// PAS ENCORE utilisees par les generateurs (devis/facture). Le rendu sera
// branche dans V3.0b a V3.0e.

import type { jsPDF } from 'jspdf'

// Hanken Grotesk (normal) - HankenGrotesk-400.ttf (31 Ko)
export const HANKEN_GROTESK_400 = ''

// Hanken Grotesk (medium) - HankenGrotesk-500.ttf (31 Ko)
export const HANKEN_GROTESK_500 = ''

// Hanken Grotesk (semibold) - HankenGrotesk-600.ttf (31 Ko)
export const HANKEN_GROTESK_600 = ''

// Hanken Grotesk (bold) - HankenGrotesk-700.ttf (31 Ko)
export const HANKEN_GROTESK_700 = ''

// Hanken Grotesk (extrabold) - HankenGrotesk-800.ttf (31 Ko)
export const HANKEN_GROTESK_800 = ''

// Spline Sans Mono (normal) - SplineSansMono-400.ttf (24 Ko)
export const SPLINE_SANS_MONO_400 = ''

// Spline Sans Mono (medium) - SplineSansMono-500.ttf (24 Ko)
export const SPLINE_SANS_MONO_500 = ''

// Spline Sans Mono (semibold) - SplineSansMono-600.ttf (24 Ko)
export const SPLINE_SANS_MONO_600 = ''

interface PdfFontMeta {
  varName: string
  vfsName: string
  base64: string
  family: string
  /**
   * Le style jsPDF de la police (passe a addFont + setFont).
   *
   * jsPDF n'a nativement que 4 styles bien reconnus (normal/bold/italic/bolditalic).
   * Pour les poids intermediaires on enregistre la police sous un style "custom"
   * (medium, semibold, extrabold) et on l'appelle via doc.setFont(family, style).
   */
  style: string
}

const PDF_FONTS: PdfFontMeta[] = [
  { varName: 'HANKEN_GROTESK_400', vfsName: 'HankenGrotesk-Regular.ttf',   base64: HANKEN_GROTESK_400, family: 'Hanken Grotesk', style: 'normal'    },
  { varName: 'HANKEN_GROTESK_500', vfsName: 'HankenGrotesk-Medium.ttf',    base64: HANKEN_GROTESK_500, family: 'Hanken Grotesk', style: 'medium'    },
  { varName: 'HANKEN_GROTESK_600', vfsName: 'HankenGrotesk-SemiBold.ttf',  base64: HANKEN_GROTESK_600, family: 'Hanken Grotesk', style: 'semibold'  },
  { varName: 'HANKEN_GROTESK_700', vfsName: 'HankenGrotesk-Bold.ttf',      base64: HANKEN_GROTESK_700, family: 'Hanken Grotesk', style: 'bold'      },
  { varName: 'HANKEN_GROTESK_800', vfsName: 'HankenGrotesk-ExtraBold.ttf', base64: HANKEN_GROTESK_800, family: 'Hanken Grotesk', style: 'extrabold' },
  { varName: 'SPLINE_SANS_MONO_400', vfsName: 'SplineSansMono-Regular.ttf',  base64: SPLINE_SANS_MONO_400, family: 'Spline Sans Mono', style: 'normal'   },
  { varName: 'SPLINE_SANS_MONO_500', vfsName: 'SplineSansMono-Medium.ttf',   base64: SPLINE_SANS_MONO_500, family: 'Spline Sans Mono', style: 'medium'   },
  { varName: 'SPLINE_SANS_MONO_600', vfsName: 'SplineSansMono-SemiBold.ttf', base64: SPLINE_SANS_MONO_600, family: 'Spline Sans Mono', style: 'semibold' },
]

/**
 * Enregistre toutes les polices Hanken Grotesk + Spline Sans Mono dans un
 * document jsPDF existant.
 *
 * A appeler en debut de generateDevisPdf() / generateFacturePdf(), AVANT
 * tout setFont(). L'enregistrement se fait via addFileToVFS + addFont sur le
 * document local (pas globalement) : aucun effet de bord entre PDF.
 *
 * Une fois enregistrees, les polices se selectionnent via :
 *   doc.setFont('Hanken Grotesk', 'normal')   // 400
 *   doc.setFont('Hanken Grotesk', 'medium')   // 500
 *   doc.setFont('Hanken Grotesk', 'semibold') // 600
 *   doc.setFont('Hanken Grotesk', 'bold')     // 700
 *   doc.setFont('Hanken Grotesk', 'extrabold')// 800
 *   doc.setFont('Spline Sans Mono', 'normal'  | 'medium' | 'semibold')
 *
 * V3.0a : helper present mais pas encore appele - le rendu PDF actuel
 * (Helvetica) reste intact. Le branchement se fera en V3.0b.
 */
export function registerPdfFonts(doc: jsPDF): void {
  for (const f of PDF_FONTS) {
    doc.addFileToVFS(f.vfsName, f.base64)
    doc.addFont(f.vfsName, f.family, f.style)
  }
}

/**
 * Liste des polices enregistrees - utile pour debug ou tests unitaires.
 * Ne renvoie PAS les chaines base64 (trop volumineuses).
 */
export function listRegisteredPdfFonts(): Array<{ family: string; style: string; vfsName: string }> {
  return PDF_FONTS.map(({ family, style, vfsName }) => ({ family, style, vfsName }))
}
